param([string]$SourceRoot=(Split-Path (Split-Path $PSScriptRoot -Parent) -Parent))
$ErrorActionPreference='Stop'
foreach($data in @(@('academy','Academy'),@('blog','Blog'),@('codex','Codex'))){$name=$data[0];$title=$data[1];$class="${title}Mailqueue";$pluginsDist="$SourceRoot\dist\$title\plugins";$outDist="$SourceRoot\dist\$title\dist";New-Item -ItemType Directory -Path $pluginsDist,$outDist -Force|Out-Null;$target="$pluginsDist\mailqueue";if(Test-Path $target){Remove-Item -LiteralPath $target -Recurse -Force};New-Item -ItemType Directory -Path $target|Out-Null;Copy-Item "$SourceRoot\extensions\post-mail\task\*" $target -Recurse;Get-ChildItem $target -Recurse -File|ForEach-Object{$text=[IO.File]::ReadAllText($_.FullName).Replace('FamilyNameMailqueue',$class).Replace('FAMILYNAME',$name.ToUpperInvariant()).Replace('FamilyTitle',$title).Replace('familyname',$name);[IO.File]::WriteAllText($_.FullName,$text,[Text.UTF8Encoding]::new($false))};Rename-Item "$target\mailqueue.xml" "${name}_mailqueue.xml";Rename-Item "$target\language\en-GB\plg_task_familyname_mailqueue.ini" "plg_task_${name}_mailqueue.ini";Rename-Item "$target\language\en-GB\plg_task_familyname_mailqueue.sys.ini" "plg_task_${name}_mailqueue.sys.ini";$zip="$outDist\plg_task_${name}_mailqueue.zip";Compress-Archive "$target\*" $zip -Force}
